using System.Security.Claims;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Antiforgery;
public static class OperationsLists
{
 internal static bool Can(ClaimsPrincipal user,bool backups,string action)=>AccessControl.Has(user,backups?AccessPermissions.Backup:AccessPermissions.System,action);
 internal static bool Can(ClaimsPrincipal user,string kind,string action)=>AccessControl.Has(user,kind=="warranties"?AccessPermissions.Warranties:kind is "backups" or "catalog-versions"?AccessPermissions.Backup:AccessPermissions.System,action);
 public static void Map(WebApplication app,string dataPath){
  var backups=new BackupFiles(dataPath);
  foreach(var kind in new[]{"mail-queue","backups","catalog-versions","warranties"}){
   var isBackup=kind=="backups";
   app.MapGet("/admin/system/"+kind,(HttpContext c)=>Can(c.User,kind,"view")?Results.Content(Page(kind),"text/html; charset=utf-8"):Results.Forbid()).RequireAuthorization();
   app.MapGet("/api/admin/system/"+kind,async(HttpContext c,MailQueue mail,Store store)=>{
    if(!Can(c.User,kind,"view"))return Results.Forbid();
    var rows=kind switch{
     "backups"=>backups.Rows(),"catalog-versions"=>store.CatalogVersionRows(),"warranties"=>new JsonArray(store.WarrantyList().Select(w=>(JsonNode)new JsonObject{
      ["id"]=w!["id"]!.ToString(),["name"]=w["productName"]?.ToString()??"Ürün",["createdUtc"]=w["created"]?.ToString()??"",
      ["detail"]=string.Join(" · ",new[]{w["businessName"]?.ToString(),w["productCode"]?.ToString(),w["serialNumber"]?.ToString()}.Where(x=>!string.IsNullOrWhiteSpace(x))),
      ["daysRemaining"]=w["daysRemaining"]?.DeepClone(),["status"]=w["status"]?.ToString()??"expired"
     }).ToArray()),_=>await mail.PendingRows(c.RequestAborted)};
    return Results.Json(new{rows,canDelete=Can(c.User,kind,"edit")});
   }).RequireAuthorization();
   app.MapPost("/api/admin/system/"+kind+"/delete",async(HttpContext c,MailQueue mail,Store store,IAntiforgery csrf)=>{
    if(!Can(c.User,kind,"edit"))return Results.Forbid();
    try{await csrf.ValidateRequestAsync(c);}catch(AntiforgeryValidationException){return Results.BadRequest(new{error="Sayfayı yenileyip tekrar deneyin."});}
    var body=await c.Request.ReadFromJsonAsync<JsonObject>();
    if(body?["ids"] is not JsonArray ids||ids.Count<1||ids.Count>1000||ids.Any(x=>x is not JsonValue v||!v.TryGetValue<string>(out _)))return Results.BadRequest(new{error="Silinecek kayıtları seçin (en fazla 1000)."});
    try{
     var selected=ids.Select(x=>x!.GetValue<string>()).ToArray();var count=kind switch{"backups"=>backups.Delete(selected),"catalog-versions"=>store.DeleteCatalogVersions(selected,AccessControl.DisplayName(c.User)),"warranties"=>store.DeleteWarranties(selected,AccessControl.DisplayName(c.User)),_=>await mail.DeletePending(selected,c.RequestAborted)};
     if(count>0&&(kind is "backups" or "mail-queue"))store.RecordAudit(isBackup?"Otomatik yedekler silindi":"Bekleyen e-postalar silindi",isBackup?"backup":"mail",count+" kayıt",AccessControl.DisplayName(c.User));
     return Results.Json(new{deleted=count});
    }catch(ArgumentException e){return Results.BadRequest(new{error=e.Message});}
   }).RequireAuthorization();
  }
 }
 public static string Page(bool backups)=>Page(backups?"backups":"mail-queue");
 public static string Page(string kind){var backups=kind=="backups";var catalog=kind=="catalog-versions";var warranties=kind=="warranties";return """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>@@TITLE@@ | İnokskar</title><link rel="stylesheet" href="/r13-interface.css?v=r22-clean"><link rel="stylesheet" href="/r13-pages.css?v=r22-2"><link rel="stylesheet" href="/r22-public-shell.css?v=r22-4"><script src="/r13-pages.js?v=central-logo-4" defer></script><style>
:root{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;color:#203e55;background:#f3f7fb}*{box-sizing:border-box}body{margin:0}.list-wrap{width:min(1000px,calc(100% - 28px));margin:24px auto 110px}.list-head{padding:20px;border:1px solid #dce6ee;background:#fff;border-radius:16px;margin-bottom:16px}.list-head h1{font-size:24px;margin:10px 0}.list-head p{font-size:14px;line-height:1.6;color:#6d8191}.back-link{font-size:13px;font-weight:650;color:#246aaa;text-decoration:none}.list-toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:13px;border:1px solid #dce6ee;border-radius:14px;background:white;margin-bottom:10px}.list-toolbar input[type=search]{flex:1;min-width:160px;min-height:42px;border:1px solid #d3dfe9;border-radius:9px;padding:9px 12px;font:inherit}.list-button{min-height:40px;padding:8px 13px;border:1px solid #ccdeed;border-radius:9px;background:#f3f8fc;color:#285c85;font:inherit;font-size:13px;font-weight:600;cursor:pointer}.list-button.danger{background:#f9eeef;color:#64202a;border-color:#dcb5bc}.list-button:disabled{opacity:.5;cursor:default}.selection{display:flex;align-items:center;gap:10px;flex-wrap:wrap;width:100%;font-size:12px}.selection[hidden]{display:none}.selection label,.record-select{display:flex;gap:7px;align-items:center;cursor:pointer}.selection input,.record-select input{width:17px;height:17px;accent-color:#2673b6}.selection button{margin-left:auto}.records{display:grid;gap:10px}.record{padding:16px;border:1px solid #dce6ee;background:white;border-radius:14px;display:grid;grid-template-columns:1fr auto;gap:10px;align-items:start}.record-main{min-width:0;overflow-wrap:anywhere}.record h2{font-size:15px;line-height:1.5;margin:0 0 7px}.record p{font-size:13px;color:#637d90;margin:4px 0;line-height:1.5}.warranty-countdown{display:inline-block;padding:5px 8px;border-radius:8px;font-size:12px;border:1px solid}.warranty-countdown.green{background:#eef9f3;color:#146448;border-color:#b5dccb}.warranty-countdown.red{background:#f9eeef;color:#64202a;border-color:#dcb5bc}.record .record-error{font-size:12px;color:#8a4553}.record-actions{display:flex;align-items:center;gap:10px;font-size:12px}.empty{background:white;border:1px dashed #ccdce9;border-radius:12px;padding:24px;text-align:center;color:#708493}#list-notice{font-size:13px;line-height:1.5;overflow-wrap:anywhere}#list-count{font-size:13px;color:#647d90}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid #3184d6;outline-offset:3px}@media(max-width:600px){.list-head{padding:16px}.list-head h1{font-size:21px}.record{grid-template-columns:1fr}.record-actions{justify-content:space-between;border-top:1px solid #edf2f6;padding-top:9px}}
</style></head><body><header class="private-brand-header"><a class="private-brand-link" href="/" aria-label="İNOKSKAR ana sayfa"><img class="private-brand-image" src="/inokskar-logo.svg" alt="İNOKSKAR"></a></header><main class="list-wrap"><section class="list-head"><a class="back-link" href="/admin/system">← Sistem durumuna dön</a><h1>@@TITLE@@</h1><p>@@DESCRIPTION@@</p></section><div class="list-toolbar"><input id="list-search" type="search" aria-label="Kayıtlarda ara" placeholder="@@SEARCH@@"><button class="list-button" id="list-refresh" type="button">Yenile</button><span id="list-count"></span><div id="selection" class="selection" hidden><label><input type="checkbox" id="select-all">Listelenenleri seç</label><span id="selected-count">0 seçildi</span><button class="list-button danger" id="delete-selected" type="button" disabled>Seçilenleri sil</button></div></div><p id="list-notice" role="status" aria-live="polite"></p><div id="records" class="records"></div></main><script>
const kind='@@KIND@@',isWarranty=kind==='warranties',isArchive=kind==='catalog-versions'||kind==='warranties',isBackup=@@BACKUP@@,api='/api/admin/system/@@KIND@@';let rows=[],visible=[],canDelete=false,busy=false;const selected=new Set();const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const date=v=>v?new Date(v).toLocaleString('tr-TR'):'Tarih yok';const size=v=>Number(v||0)<1048576?(Number(v||0)/1024).toLocaleString('tr-TR',{maximumFractionDigits:1})+' KB':(Number(v||0)/1048576).toLocaleString('tr-TR',{maximumFractionDigits:2})+' MB';
function selection(){ $('selected-count').textContent=selected.size+' seçildi';$('delete-selected').disabled=busy||!selected.size;const all=$('select-all');all.disabled=busy||!visible.length;all.checked=visible.length>0&&visible.every(x=>selected.has(x.id));all.indeterminate=visible.some(x=>selected.has(x.id))&&!all.checked;document.querySelectorAll('[data-remove],[data-select]').forEach(x=>x.disabled=busy);$('list-refresh').disabled=busy;$('list-search').disabled=busy;}
function render(){const q=$('list-search').value.trim().toLocaleLowerCase('tr-TR');visible=rows.filter(x=>[x.name,x.to,x.subject,x.detail].join(' ').toLocaleLowerCase('tr-TR').includes(q));$('list-count').textContent=visible.length+' / '+rows.length+' kayıt';$('selection').hidden=!canDelete;$('records').innerHTML=visible.length?visible.map(x=>`<article class="record"><div class="record-main"><h2>${esc(isBackup||isArchive?x.name:x.subject)}</h2>${isArchive?`<p>${esc(x.detail)}</p>${isWarranty?`<p><span class="warranty-countdown ${x.status==='active'&&Number(x.daysRemaining)>30?'green':'red'}">${x.status==='active'?esc(x.daysRemaining)+' gün kaldı':'Garanti süresi doldu'}</span></p>`:`<p>${esc(date(x.createdUtc))}</p>`}`:isBackup?`<p>${esc(date(x.createdUtc))} · ${esc(size(x.bytes))}</p>`:`<p>Alıcı: ${esc(x.to)}</p><p>${esc(date(x.createdUtc))} · ${esc(x.attempts)} deneme</p>${x.lastError?`<p class="record-error">${esc(x.lastError)}</p>`:''}`}</div>${canDelete?`<div class="record-actions"><label class="record-select"><input type="checkbox" data-select="${esc(x.id)}" ${selected.has(x.id)?'checked':''} aria-label="${esc(isBackup||isArchive?x.name:x.subject)} kaydını seç">Seç</label><button type="button" class="list-button danger" data-remove="${esc(x.id)}">Sil</button></div>`:''}</article>`).join(''):'<div class="empty">'+(rows.length?'Aramanızla eşleşen kayıt yok.':isArchive?'Kayıt bulunamadı.':isBackup?'Otomatik yedek dosyası yok.':'Bekleyen e-posta yok.')+'</div>';selection();}
async function load(){const r=await fetch(api,{cache:'no-store'});if(r.status===401){location.href='/login';return;}const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Liste alınamadı. Yetkinizi kontrol edin.');rows=data.rows||[];canDelete=data.canDelete===true;selected.clear();render();}
async function remove(ids){if(busy||!canDelete||!ids.length)return;if(ids.length>1000){$('list-notice').textContent='Tek işlemde en fazla 1000 kayıt seçin.';return;}if(!confirm(ids.length+(isWarranty?' garanti kaydı silinecek; müşteri garanti sorgusunda artık görünmeyecek.':isArchive?' geçmiş katalog sürümü silinecek. Güncel katalog korunacak.':isBackup?' yedek dosyası kalıcı olarak silinecek.':' bekleyen e-posta silinecek ve gönderilmeyecek.')+' Onaylıyor musunuz?'))return;busy=true;selection();$('list-notice').textContent='Siliniyor…';try{const c=await fetch('/api/security/csrf',{cache:'no-store'});if(!c.ok)throw Error('Oturumunuzu yenileyin.');const token=(await c.json()).token;const r=await fetch(api+'/delete',{method:'POST',headers:{'Content-Type':'application/json','X-INOKSKAR-CSRF':token},body:JSON.stringify({ids})});const b=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.error||'Silme işlemi tamamlanamadı.');await load();$('list-notice').textContent=b.deleted+' kayıt silindi.';}catch(e){$('list-notice').textContent=e.message;}finally{busy=false;selection();}}
$('records').onchange=e=>{const id=e.target.dataset.select;if(!id)return;e.target.checked?selected.add(id):selected.delete(id);selection();};$('records').onclick=e=>{const b=e.target.closest('[data-remove]');if(b)remove([b.dataset.remove]);};$('select-all').onchange=e=>{visible.forEach(x=>e.target.checked?selected.add(x.id):selected.delete(x.id));render();};$('delete-selected').onclick=()=>remove([...selected]);$('list-search').oninput=()=>{selected.clear();render();};$('list-refresh').onclick=()=>load().catch(e=>$('list-notice').textContent=e.message);load().catch(e=>$('list-notice').textContent=e.message);
</script></body></html>
""".Replace("@@TITLE@@",catalog?"Katalog sürüm geçmişi":warranties?"Garanti kayıtları":backups?"Otomatik yedek dosyaları":"Bekleyen e-postalar").Replace("@@DESCRIPTION@@",catalog?"Geçmiş katalog sürümlerini yönetin. Güncel katalog ve sürüm numarası silinmez.":warranties?"Garanti kayıtlarını işletme, ürün ve seri numarasına göre yönetin.":backups?"Otomatik yedeklerinizi tarih ve boyut bilgileriyle yönetin.":"Henüz gönderilmemiş e-postaları görüntüleyin ve kuyruktan kaldırın.").Replace("@@SEARCH@@",catalog?"Sürüm açıklamasına göre ara":warranties?"İşletme, ürün veya seri numarası ara":backups?"Dosya adına göre ara":"Alıcı veya konuya göre ara").Replace("@@BACKUP@@",backups?"true":"false").Replace("@@KIND@@",kind);
 }
